"use server";

import { apiv3Get } from "@/lib/apiv3";

/**
 * Server action — apiv3 b2c uçları `X-App-Token` (server-side gizli) ister; bu yüzden
 * client component'ler bu fonksiyonları RPC ile çağırır, token asla istemciye sızmaz.
 * (Mevcut `app/actions/*` desenleriyle aynı yaklaşım.)
 */

/** Ülke listesi (id, name, phone_code, slug) — apiv3 countries. */
export default async function getLocations() {
  const res = await apiv3Get("/countries", { cache: "force-cache" });
  const json = await res.json();
  return json.data ?? [];
}

/** Bir ülkenin şehir/eyaletleri — apiv3 countries/{id}/cities. */
export async function getCities(countryId: number | string) {
  if (!countryId) return [];
  const res = await apiv3Get(`/countries/${countryId}/cities`, { cache: "force-cache" });
  if (!res.ok) return [];
  const json = await res.json();
  return json.data ?? [];
}
